   "export { diffLines, lines, stats } from './diff.ts';\nexport type { Op } from './diff.ts';\nexport { hunks, unified } from './unified.ts';\nexport type { Hunk } from './unified.ts';\nexport { applyPatch } from './patch.ts';\n",
